const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const headers = reqItem.headers || {};
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'direct').split(',')[0].trim();
const ua = String(headers['user-agent'] || '').slice(0, 180);
const visitorKey = `${ip}|${ua}`.replace(/'/g, "''");

const level = ['ALL', 'NECESSARY_ONLY', 'CUSTOM'].includes(body.consent_level)
  ? body.consent_level
  : 'ALL';
const analytics = level === 'ALL' ? true : (level === 'NECESSARY_ONLY' ? false : !!body.analytics_cookies);
const marketing = level === 'ALL' ? true : (level === 'NECESSARY_ONLY' ? false : !!body.marketing_cookies);

return [{
  json: {
    visitorKey,
    consent_level: level,
    necessary_cookies: true,
    analytics_cookies: analytics,
    marketing_cookies: marketing,
    policy_version: String(body.policy_version || 'v1.0-2026-10').replace(/'/g, "''"),
    region_code: String(body.region_code || 'US').replace(/'/g, "''")
  }
}];

